    "用来从字幕里筛你可能还不熟的词。设了之后，打开视频会先给一份生词库，可以先过一遍再看。不是官方考纲，先不设也可以。": "Used to filter words you may not know yet from captions. After you set it, opening a video gives you a vocab list to skim first. Not an official syllabus — you can skip this.",
