    "下面两把钥匙用你自己的账号，不提供额度。填上才能读字幕、拆知识、查生词。": "下の2つのキーは自分のアカウントで。枠はこちらでは出しません。入れると字幕、分解、単語調べが使えます。",
    "DeepSeek · 拆解和查词": "DeepSeek · 分解と単語",
    "打开 API Keys 页面，没有账号会先让你注册。": "API Keys のページを開く。アカウントがなければ先に登録になる。",
