    "不确定就用默认，之后随时能改。Flash 快、便宜；Pro 更稳，适合拆解。": "わからなければ初期のままで。あとから変えられる。Flash は速くて安い。Pro は安定して分解向き。",
    "日常默认 · 翻译、提问、做成图": "日常の初期値 · 翻訳、質問、図",
