    "用来从字幕里筛你可能还不熟的词。设了之后，打开视频会先给一份生词库，可以先过一遍再看。不是官方考纲，先不设也可以。": "字幕から、まだ弱い語を拾うため。設定すると、動画を開いたときに単語リストが先に出る。公式の出題範囲ではない。今は空でもよい。",
