    "看见不够，就动手改。": "부족한 걸 보면, 직접 고친다.",
    "改完之后，往更好去。": "고친 뒤에는 더 나아지게.",
    "两个字合在一起，叫持续精进：今天比昨天清楚一点，明天再清楚一点。": "두 글자를 합치면 지속적 개선: 오늘은 어제보다 조금 더 분명하게, 내일은 또 조금 더.",
    "下面两把钥匙用你自己的账号，不提供额度。填上才能读字幕、拆知识、查生词。": "아래 두 키는 본인 계정으로. 할당량은 드리지 않습니다. 넣어야 자막, 분해, 단어 조회가 됩니다.",
    "DeepSeek · 拆解和查词": "DeepSeek · 분해와 단어",
    "打开 API Keys 页面，没有账号会先让你注册。": "API Keys 페이지를 연다. 계정이 없으면 먼저 가입하게 된다.",
    "点 Create new API key，名字填「Kaizen」即可。": "Create new API key를 누르고 이름은 「Kaizen」이면 된다.",
    "立刻复制完整 Key（一般只显示一次）。": "바로 키 전체를 복사한다(보통 한 번만 보인다).",
    "Supadata · 字幕": "Supadata · 자막",
    "打开 Supadata 注册页，走完新手引导。": "Supadata 가입 페이지를 열고 안내를 끝까지 한다.",
    "引导里会自动生成 Key，之后可在控制台查找。": "안내에서 키가 자동으로 만들어진다. 이후 콘솔에서 찾을 수 있다.",
    "DeepSeek 用哪个": "DeepSeek 어떤 걸",
    "不确定就用默认，之后随时能改。Flash 快、便宜；Pro 更稳，适合拆解。": "모르겠으면 기본값. 나중에 언제든 바꿀 수 있다. Flash는 빠르고 싸고, Pro는 더 안정적이라 분해에 맞다.",
    "日常默认 · 翻译、提问、做成图": "일상 기본 · 번역, 질문, 그림",
    "更强 · 拆解和长笔记默认用它": "더 강함 · 분해와 긴 노트의 기본",
    "拆解也改成和上面同一个（默认拆解走 Pro）": "분해도 위와 같게 (기본 분해는 Pro)",
    "接口地址": "API 주소",
    "一般不用改": "보통은 건드리지 않음",
    "英语大概到哪": "영어는 대략 어디쯤",
    "用来从字幕里筛你可能还不熟的词。设了之后，打开视频会先给一份生词库，可以先过一遍再看。不是官方考纲，先不设也可以。": "자막에서 아직 익숙하지 않을 단어를 고른다. 설정하면 영상을 열 때 단어 목록이 먼저 나온다. 공식 출제범위는 아니다. 지금은 비워도 된다.",
    "四级": "CET-4",
