    "看视频很容易滑过去。在这里停一下。": "영상은 쉽게 스쳐 지나간다. 여기서 잠깐 멈추자.",
    "打开一支有字幕的 YouTube 或 B 站，就开始。": "자막 있는 YouTube나 빌리빌리를 열면 시작한다.",
    "看视频前，先设英语大概到哪": "보기 전에 영어가 어디쯤인지 먼저 정하기",
    "设了之后，打开视频会先给一份可能生词库，可以先过一遍再看。": "설정하면 영상을 열 때 생단어 후보가 먼저 나온다. 한번 훑고 봐도 된다.",
    "重试": "다시 시도",
