    "点节点可跳转、展开或打开对应知识块。": "노드를 누르면 이동, 펼치기, 해당 블록을 연다.",
    "先问主张、某一句，或你正看到的地方。答案里的时间能点。": "주장, 한 문장, 또는 지금 보는 곳을 먼저 묻는다. 답의 시간은 누를 수 있다.",
