    "侧栏没接到视频，先循环附近几秒": "Seitenleiste hängt an keinem Video. Erst ein paar Sekunden in der Nähe loopen.",
    "点重试，或换一支有字幕的视频。": "Erneut versuchen oder ein Video mit Untertiteln wählen.",
    "视频页没接上。点一下视频再试。": "Videoseite nicht verbunden. Video anklicken und nochmal.",
    "续读提示没生成出来，时间还在。": "Weiterlesen-Hinweis fehlgeschlagen. Die Zeit bleibt.",
