    "看见不够，就动手改。": "Siehst du, dass es nicht reicht — ändere es.",
    "改完之后，往更好去。": "Nach der Änderung: mach es besser.",
    "两个字合在一起，叫持续精进：今天比昨天清楚一点，明天再清楚一点。": "Zusammen heißt das: stetig besser. Heute etwas klarer als gestern, morgen noch etwas klarer.",
    "下面两把钥匙用你自己的账号，不提供额度。填上才能读字幕、拆知识、查生词。": "Beide Keys kommen von deinen Konten. Kein Guthaben von uns. Erst dann: Untertitel, Zerlegen, Wörter nachschlagen.",
    "DeepSeek · 拆解和查词": "DeepSeek · Zerlegen und Nachschlagen",
    "打开 API Keys 页面，没有账号会先让你注册。": "Öffne die API-Keys-Seite. Ohne Konto wirst du zuerst registriert.",
    "点 Create new API key，名字填「Kaizen」即可。": "Klicke Create new API key. Name: „Kaizen“.",
    "立刻复制完整 Key（一般只显示一次）。": "Kopiere den ganzen Key sofort (wird meist nur einmal gezeigt).",
    "Supadata · 字幕": "Supadata · Untertitel",
    "打开 Supadata 注册页，走完新手引导。": "Öffne die Supadata-Anmeldung und geh die Einführung durch.",
    "引导里会自动生成 Key，之后可在控制台查找。": "Die Einführung erzeugt einen Key. Später im Dashboard zu finden.",
    "DeepSeek 用哪个": "Welches DeepSeek",
    "不确定就用默认，之后随时能改。Flash 快、便宜；Pro 更稳，适合拆解。": "Unsicher? Standard lassen, später änderbar. Flash ist schnell und günstig; Pro ist stabiler zum Zerlegen.",
    "日常默认 · 翻译、提问、做成图": "Alltag · übersetzen, fragen, Karten",
    "更强 · 拆解和长笔记默认用它": "Stärker · Standard für Zerlegen und lange Notizen",
    "拆解也改成和上面同一个（默认拆解走 Pro）": "Zum Zerlegen dasselbe Modell (Standard: Pro)",
    "接口地址": "API-Adresse",
