    "英语大概到哪": "Ungefähr: wie weit ist dein Englisch",
    "用来从字幕里筛你可能还不熟的词。设了之后，打开视频会先给一份生词库，可以先过一遍再看。不是官方考纲，先不设也可以。": "Filtert aus Untertiteln Wörter, die du noch nicht sicher kannst. Danach gibt ein Video zuerst eine Liste. Kein offizieller Lehrplan — du kannst es lassen.",
