    "点一下就保存。不是官方考纲。": "Нажали — сохранилось. Это не официальная программа.",
    "记下了，打开侧栏后会写入金句": "Записано. Попадёт в цитаты, когда панель открыта.",
    "铺好之后就可以划线、拆知识。": "Когда разложено — пометки и разбор.",
    "这支视频可能确实没有字幕轨。": "У этого видео, возможно, нет дорожки субтитров.",
    "知识块没拆出来，点拆页再试。": "Блоки не вышли. Откройте блоки и ещё раз.",
