    "下面两把钥匙用你自己的账号，不提供额度。填上才能读字幕、拆知识、查生词。": "Оба ключа — из ваших аккаунтов. Квоту не даём. Заполните, чтобы читать субтитры, разбирать и смотреть слова.",
