    "打开 API Keys 页面，没有账号会先让你注册。": "Откройте страницу API Keys. Без аккаунта сначала попросят зарегистрироваться.",
    "点 Create new API key，名字填「Kaizen」即可。": "Нажмите Create new API key. Имя — «Kaizen».",
    "立刻复制完整 Key（一般只显示一次）。": "Сразу скопируйте ключ целиком (обычно показывают один раз).",
    "Supadata · 字幕": "Supadata · субтитры",
    "打开 Supadata 注册页，走完新手引导。": "Откройте регистрацию Supadata и пройдите знакомство.",
    "引导里会自动生成 Key，之后可在控制台查找。": "В знакомстве ключ создаётся сам. Потом его можно найти в консоли.",
    "DeepSeek 用哪个": "Какой DeepSeek",
    "不确定就用默认，之后随时能改。Flash 快、便宜；Pro 更稳，适合拆解。": "Не уверены — оставьте по умолчанию, потом поменяете. Flash быстрый и дешёвый; Pro стабильнее для разбора.",
    "日常默认 · 翻译、提问、做成图": "На каждый день · перевод, вопросы, схемы",
    "更强 · 拆解和长笔记默认用它": "Сильнее · по умолчанию для разбора и длинных заметок",
    "拆解也改成和上面同一个（默认拆解走 Pro）": "Для разбора тот же, что сверху (по умолчанию Pro)",
    "接口地址": "Адрес API",
    "一般不用改": "Обычно не трогать",
    "英语大概到哪": "Примерно какой у вас английский",
    "用来从字幕里筛你可能还不熟的词。设了之后，打开视频会先给一份生词库，可以先过一遍再看。不是官方考纲，先不设也可以。": "Чтобы отсеять из субтитров ещё незнакомые слова. После настройки видео сначала даст список. Это не официальная программа — можно не ставить.",
    "四级": "CET-4",
