    "看视频很容易滑过去。在这里停一下。": "Видео легко проскакивает. Остановись здесь.",
    "打开一支有字幕的 YouTube 或 B 站，就开始。": "Откройте YouTube или Bilibili с субтитрами — и можно начинать.",
    "看视频前，先设英语大概到哪": "Перед просмотром задайте примерный английский",
    "设了之后，打开视频会先给一份可能生词库，可以先过一遍再看。": "После настройки видео сначала даст список возможных новых слов.",
