    "点节点可跳转、展开或打开对应知识块。": "Нажмите узел — переход, раскрытие или блок.",
    "先问主张、某一句，或你正看到的地方。答案里的时间能点。": "Спросите про тезис, фразу или место, где вы. Время в ответе нажимается.",
