    "两个字合在一起，叫持续精进：今天比昨天清楚一点，明天再清楚一点。": "Digabung artinya perbaikan terus-menerus: hari ini sedikit lebih jernih dari kemarin, besok lagi.",
    "下面两把钥匙用你自己的账号，不提供额度。填上才能读字幕、拆知识、查生词。": "Kedua kunci pakai akun Anda sendiri. Kami tidak memberi kuota. Isi dulu agar bisa baca subtitle, uraikan, dan cek kata.",
    "DeepSeek · 拆解和查词": "DeepSeek · uraian dan kata",
    "打开 API Keys 页面，没有账号会先让你注册。": "Buka halaman API Keys. Jika belum punya akun, Anda diminta daftar dulu.",
    "点 Create new API key，名字填「Kaizen」即可。": "Klik Create new API key. Namanya cukup «Kaizen».",
