    "Supadata · 字幕": "Supadata · subtitle",
    "打开 Supadata 注册页，走完新手引导。": "Buka halaman daftar Supadata dan selesaikan panduan.",
    "引导里会自动生成 Key，之后可在控制台查找。": "Di panduan, Key dibuat otomatis. Nanti bisa dicari di dasbor.",
    "DeepSeek 用哪个": "DeepSeek yang mana",
    "不确定就用默认，之后随时能改。Flash 快、便宜；Pro 更稳，适合拆解。": "Ragu? Pakai bawaan, nanti bisa diubah. Flash cepat dan murah; Pro lebih stabil untuk uraian.",
    "日常默认 · 翻译、提问、做成图": "Harian · terjemah, tanya, peta",
    "更强 · 拆解和长笔记默认用它": "Lebih kuat · bawaan untuk uraian dan catatan panjang",
    "拆解也改成和上面同一个（默认拆解走 Pro）": "Uraian ikut yang di atas (bawaan uraian: Pro)",
    "接口地址": "Alamat API",
    "一般不用改": "Biasanya tidak perlu diubah",
    "英语大概到哪": "Bahasa Inggris kira-kira di mana",
    "用来从字幕里筛你可能还不熟的词。设了之后，打开视频会先给一份生词库，可以先过一遍再看。不是官方考纲，先不设也可以。": "Untuk menyaring kata yang mungkin belum Anda kuasai dari subtitle. Setelah disetel, membuka video memberi daftar dulu. Bukan silabus resmi — boleh dikosongkan.",
