    "更强 · 拆解和长笔记默认用它": "แรงกว่า · ค่าเริ่มต้นสำหรับแยกและโน้ตยาว",
    "拆解也改成和上面同一个（默认拆解走 Pro）": "การแยกใช้ตัวเดียวกับด้านบน (ค่าเริ่มต้นแยกใช้ Pro)",
    "接口地址": "ที่อยู่ API",
    "一般不用改": "โดยทั่วไปไม่ต้องแก้",
    "英语大概到哪": "อังกฤษประมาณไหน",
    "用来从字幕里筛你可能还不熟的词。设了之后，打开视频会先给一份生词库，可以先过一遍再看。不是官方考纲，先不设也可以。": "ใช้กรองคำที่คุณอาจยังไม่ชำนาญจากคำบรรยาย ตั้งแล้ว เปิดวิดีโอจะได้คลังคำก่อน ไม่ใช่หลักสูตรทางการ ยังไม่ตั้งก็ได้",
    "四级": "CET-4",
