    "先不设": "ยังไม่ตั้ง",
    "总分（选填）": "คะแนนรวม (ไม่บังคับ)",
    "保存并开始": "บันทึกแล้วเริ่ม",
    "Key 只存在这台电脑的浏览器里。": "Key อยู่ในเบราว์เซอร์ของเครื่องนี้เท่านั้น",
    "联系作者 · 微信 942966642": "ติดต่อ · WeChat 942966642",
    "跳过": "ข้าม",
