    "设置": "ตั้งค่า",
    "改善": "ปรับปรุง",
    "看视频很容易滑过去。在这里停一下。": "ดูวิดีโอแล้วหลุดง่าย หยุดตรงนี้ก่อน",
    "打开一支有字幕的 YouTube 或 B 站，就开始。": "เปิด YouTube หรือบิลิบิลิที่มีคำบรรยาย ก็เริ่มได้",
    "看视频前，先设英语大概到哪": "ก่อนดู ตั้งก่อนว่าอังกฤษประมาณไหน",
    "设了之后，打开视频会先给一份可能生词库，可以先过一遍再看。": "ตั้งแล้ว เปิดวิดีโอจะได้คลังคำที่อาจยังใหม่ ดูรอบก่อนแล้วค่อยดู",
    "重试": "ลองใหม่",
    "先复习到期的卡": "ทบทวนการ์ดที่ถึงกำหนดก่อน",
    "阅读": "อ่าน",
    "提问": "ถาม",
