    "时间线": "ไทม์ไลน์",
    "点节点可跳转、展开或打开对应知识块。": "คลิกโหนดเพื่อกระโดด ขยาย หรือเปิดบล็อก",
    "先问主张、某一句，或你正看到的地方。答案里的时间能点。": "ถามข้ออ้าง ประโยคหนึ่ง หรือตรงที่กำลังดู เวลาในคำตอบกดได้",
    "发送": "ส่ง",
