    "精选": "คัดแล้ว",
    "看完": "ดูจบ",
    "按视频看每支的知识块和金句；按概念看同一件事在不同视频里怎么讲。": "ตามวิดีโอ: บล็อกและประโยคเด่นของแต่ละคลิป ตามแนวคิด: เรื่องเดียวกันถูกเล่าต่างกันอย่างไร",
