    "对照字幕批改": "เทียบกับคำบรรยาย",
    "退出沉浸": "ออกจากโหมดจ่อ",
    "两个 Key 都要有。改完点保存。不确定模型就用默认。": "ต้องมีทั้งสอง Key แก้แล้วกดบันทึก ไม่แน่เรื่องโมเดลใช้ค่าเริ่มต้น",
    "日常 · 翻译、提问、分块、做成图": "ใช้ประจำ · แปล ถาม หั่น ทำแผนภาพ",
